INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00022000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 22), 'unit22-lesson1', 'Too … to → So … that', 'Sentences using ''too … to'' can be transformed into ''so … that'' sentences. ''Too + adjective + to + V1'' becomes ''so + adjective + that + cannot/could not + V1''. For different subjects, ''too + adj + for person + to + V1'' becomes ''so + adj + that + person + cannot/could not + V1''.', '{"details":[{"concept":"Same subject conversion","explanation":"Replace ''too'' with ''so'' and add ''that … cannot/could not'' before the verb.","example":"He is too proud to beg. → He is so proud that he cannot beg.","burmese":"သူက အရမ်းမာနကြီးလို့ မတောင်းနိုင်ဘူး။"},{"concept":"Different subject conversion","explanation":"Move the ''for person'' part after ''that'' as the subject of the result clause.","example":"The bag was too heavy for me to lift. → The bag was so heavy that I could not lift it.","burmese":"အိတ်က ငါအတွက် မမော့နိုင်လောက်အောင် လေးတယ်။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00022001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 22), 'unit22-lesson2', 'So … that → Too … to', 'Sentences using ''so … that'' can be transformed into ''too … to'' sentences. ''So + adjective + that + cannot/could not + V1'' becomes ''too + adjective + to + V1''. When the result clause has a different subject, use ''too + adj + for person + to + V1''.', '{"details":[{"concept":"Same subject conversion","explanation":"Remove ''that cannot/could not'' and replace ''so'' with ''too''.","example":"This exercise is so difficult that I cannot do it. → This exercise is too difficult for me to do.","burmese":"ဒီအားကစားက ငါလုပ်လို့မရနိုင်လောက်အောင် ခက်တယ်။"},{"concept":"Different subject conversion","explanation":"The subject of the ''that'' clause becomes ''for + person'' in the ''too … to'' form.","example":"There are so many birds that I cannot count them. → There are too many birds for me to count.","burmese":"ငါရေတွက်လို့မရနိုင်လောက်အောင် ငှက်တွေ အများကြီးရှိတယ်။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00022000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 22), 'unit22-ex1', 'multiple_choice', 'Transform the following sentences between ''too … to'' and ''so … that''.', '[{"id":2201,"question":"The theory was too complicated for me to understand. Transform to ''so … that''.","options":["so complicated that I could not understand it","so complicated that I can understand it","too complicated that I could not understand it"],"answer":"so complicated that I could not understand it","explanation":"Transform ''too … for … to'' → ''so … that … could not''. ''Can'' is wrong tense. ''Too … that'' mixes structures. ''So … that'' ကို ''too … to'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2202,"question":"She is too impatient to be a teacher. Transform to ''so … that''.","options":["so impatient that she cannot be a teacher","so impatient that she can be a teacher","too impatient that she cannot be a teacher"],"answer":"so impatient that she cannot be a teacher","explanation":"Transform ''too … to'' → ''so … that … cannot''. ''Can'' changes meaning. ''Too … that'' is wrong. ''So … that'' ကို ''too … to'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2203,"question":"The tea is too hot for me to drink. Transform to ''so … that''.","options":["so hot that I cannot drink it","so hot that I can drink it","too hot that I cannot drink it"],"answer":"so hot that I cannot drink it","explanation":"Transform ''too … for … to'' → ''so … that … cannot''. ''Can'' is wrong. ''Too … that'' is wrong structure. ''So … that'' ကို ''too … to'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2204,"question":"He is too haughty to apologise. Transform to ''so … that''.","options":["so haughty that he cannot apologise","so haughty that he can apologise","too haughty that he cannot apologise"],"answer":"so haughty that he cannot apologise","explanation":"Transform ''too … to'' → ''so … that … cannot''. ''Can'' changes meaning. ''Too … that'' is wrong. ''So … that'' ကို ''too … to'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2205,"question":"The box was too heavy for him to lift. Transform to ''so … that''.","options":["so heavy that he could not lift it","so heavy that he can lift it","too heavy that he could not lift it"],"answer":"so heavy that he could not lift it","explanation":"Transform ''too … for … to'' → ''so … that … could not''. ''Can'' is wrong tense. ''Too … that'' is wrong. ''So … that'' ကို ''too … to'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2206,"question":"She is too selfish to help others. Transform to ''so … that''.","options":["so selfish that she cannot help others","so selfish that she can help others","too selfish that she cannot help others"],"answer":"so selfish that she cannot help others","explanation":"Transform ''too … to'' → ''so … that … cannot''. ''Can'' changes meaning. ''Too … that'' is wrong. ''So … that'' ကို ''too … to'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2207,"question":"This exercise is so difficult that I cannot do it. Transform to ''too … to''.","options":["too difficult for me to do","too difficult to do it","so difficult for me to do it"],"answer":"too difficult for me to do","explanation":"Transform ''so … that … cannot'' → ''too … for … to''. ''Too difficult to do it'' is missing ''for me''. ''So … for'' mixes structures. ''Too … to'' ကို ''so … that'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2208,"question":"There are so many birds that I cannot count them. Transform to ''too … to''.","options":["too many birds for me to count","too many birds to count them","so many birds for me to count them"],"answer":"too many birds for me to count","explanation":"Transform ''so … that … cannot'' → ''too … for … to''. ''Too many birds to count them'' is redundant. ''So … for'' mixes structures. ''Too … to'' ကို ''so … that'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2209,"question":"Those flowers are so pretty that we should not pluck them. Transform to ''too … to''.","options":["too pretty for us to pluck","too pretty to pluck them","so pretty for us to pluck them"],"answer":"too pretty for us to pluck","explanation":"Transform ''so … that … should not'' → ''too … for … to''. ''Too pretty to pluck them'' is redundant. ''So … for'' mixes structures. ''Too … to'' ကို ''so … that'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2210,"question":"The print is so small that I cannot read it. Transform to ''too … to''.","options":["too small for me to read","too small to read it","so small for me to read it"],"answer":"too small for me to read","explanation":"Transform ''so … that … cannot'' → ''too … for … to''. ''Too small to read it'' is redundant. ''So … for'' mixes structures. ''Too … to'' ကို ''so … that'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2211,"question":"He ran too fast for me to catch up. Transform to ''so … that''.","options":["so fast that I could not catch up","so fast that I can catch up","too fast that I could not catch up"],"answer":"so fast that I could not catch up","explanation":"Transform ''too … for … to'' → ''so … that … could not''. ''Can'' is wrong tense. ''Too … that'' is wrong. ''So … that'' ကို ''too … to'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2212,"question":"The news is too good to be true. Transform to ''so … that''.","options":["so good that it cannot be true","so good that it can be true","too good that it cannot be true"],"answer":"so good that it cannot be true","explanation":"Transform ''too … to'' → ''so … that … cannot''. ''Can'' changes meaning. ''Too … that'' is wrong. ''So … that'' ကို ''too … to'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2213,"question":"The bank is too far for me to walk to it. Transform to ''so … that''.","options":["so far that I cannot walk to it","so far that I can walk to it","too far that I cannot walk to it"],"answer":"so far that I cannot walk to it","explanation":"Transform ''too … for … to'' → ''so … that … cannot''. ''Can'' is wrong. ''Too … that'' is wrong. ''So … that'' ကို ''too … to'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2214,"question":"The current of the river was so strong that we could not swim in it. Transform to ''too … to''.","options":["too strong for us to swim in","too strong to swim in it","so strong for us to swim in it"],"answer":"too strong for us to swim in","explanation":"Transform ''so … that … could not'' → ''too … for … to''. ''Too strong to swim in it'' is redundant. ''So … for'' mixes structures. ''Too … to'' ကို ''so … that'' ပြောင်းဖို့ သုံးပါ။","points":1},{"id":2215,"question":"The eagles are flying so high that we cannot see them. Transform to ''too … to''.","options":["too high for us to see","too high to see them","so high for us to see them"],"answer":"too high for us to see","explanation":"Transform ''so … that … cannot'' → ''too … for … to''. ''Too high to see them'' is redundant. ''So … for'' mixes structures. ''Too … to'' ကို ''so … that'' ပြောင်းဖို့ သုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

